GraphChoices.blockFlatten.source:
def blockFlatten {E : Type*} (k s : ℕ) : (Fin k → Fin s → E) ≃ (Fin (k*s) → E) :=
  (Equiv.curry (Fin k) (Fin s) E).symm.trans
    (Equiv.arrowCongr finProdFinEquiv (Equiv.refl E))

