def opt (I : Instance V T) : ℕ :=
  Nat.find (show ∃ c, ∃ a : Orientation T, maxLoad I a ≤ c from
    ⟨T, (fun _ => false), maxLoad_le_length I (fun _ => false)⟩)

GraphChoices.slotAllowed.source:
def slotAllowed {m : ℕ} {α : J → ℕ} (tree : Fin m → E) (bucket : J → Finset E) :
    WitnessSlot J m α → Finset E
  | Sum.inl i => {tree i}
  | Sum.inr ⟨j,_⟩ => bucket j

GraphChoices.RandomGreedy.choice.source:
def choice (G : BaseGraph V E) (s : V → ℕ) (x : E × Bool) : Bool :=
  if s (G.left x.1) < s (G.right x.1) then true
  else if s (G.right x.1) < s (G.left x.1) then false else x.2

GraphChoices.ThresholdGreedy.replayOrien.source:
def replayOrientation (es : List (Arrival L R C)) : Orientation es.length := fun t =>
  let s := greedyRun (zeroGreedy : GreedyLoads L R) (es.take t.val)
  decide (s.left (es.get t).left < s.right (es.get t).right)

GraphChoices.ThresholdGreedy.totalVertex.source:
def totalVertexLoad [Fintype C] (α : C → ℕ) (es : List (Arrival L R C)) : L ⊕ R → ℕ :=
  Sum.elim (fun u => (∑ c, (run α es).threshold u c) + (run α es).greedyLeft u)
    (run α es).greedyRight

GraphChoices.ThresholdGreedy.totalMaxLoa.source:
def totalMaxLoad [Fintype C] (α : C → ℕ) (es : List (Arrival L R C)) : ℕ :=
  univ.sup (totalVertexLoad α es)

