GraphChoices.ThresholdGreedy.step.source:
def step (α : C → ℕ) (s : State L R C) (e : Arrival L R C) : State L R C :=
  if s.threshold e.left e.cls < α e.cls then
    { s with threshold := fun u i => s.threshold u i + if u = e.left ∧ i = e.cls then 1 else 0 }
  else if s.greedyLeft e.left < s.greedyRight e.right then
    { s with greedyLeft := fun u => s.greedyLeft u + if u = e.left then 1 else 0 }
  else
    { s with greedyRight := fun v => s.greedyRight v + if v = e.right then 1 else 0 }

GraphChoices.ThresholdGreedy.stepChoice.source:
def stepChoice (α : C → ℕ) (s : State L R C) (e : Arrival L R C) : Bool :=
  if s.threshold e.left e.cls < α e.cls then true
  else decide (s.greedyLeft e.left < s.greedyRight e.right)

GraphChoices.ThresholdGreedy.policyPrefi.source:
def policyPrefixLoad (encode : E → Arrival L R C) (α : C → ℕ) {T : ℕ}
    (ω : Fin T → E) (k : ℕ) : L ⊕ R → ℕ :=
  stateLoad (run α (((List.ofFn ω).take k).map encode))

theorem policyPrefixLoad_zero (encode : E → Arrival L R C) (α : C → ℕ) {T : ℕ}
    (ω : Fin T → E) (v : L ⊕ R) : policyPrefixLoad encode α ω 0 v = 0 := by
  cases v <;> simp [policyPrefixLoad, run, runFrom, initial, stateLoad]

GraphChoices.prunedVertices.source:
def prunedVertices (left : V → Bool) : Set V :=
  {v | left v = true ∨ 2 ≤ G.degree v}

instance decidablePrunedVertices (left : V → Bool) :
    DecidablePred (fun v => v ∈ prunedVertices G left) :=
  fun v => inferInstanceAs (Decidable (left v = true ∨ 2 ≤ G.degree v))
